"## 데이터 읽는 법": "## How to read the data",
"- 시간은 \"카테고리>항목\" 단위로 기록함. 카테고리(항목): ": "- Time is logged per \"category>item\". Categories (items): ",
"- 기록: 타이머로 재거나 직접 넣은 한 번의 집중 시간. 집중도는 끝난 뒤 스스로 매긴 1~5점(5가 가장 집중)이고, 없으면 매기지 않은 것": "- Session: one stretch of focus timed with the timer or entered manually. Focus is a self-rating of 1–5 after the session (5 = most focused); none means not rated",
"- 장기 할 일: 날짜 없이 대시보드에 적어 둔 일. 우선순위는 아이젠하워 매트릭스(급함×중요함)의 네 칸이고, \"연결된 할 일\"은 그 일에서 꺼내 날짜별 할 일로 만든 것": "- Long-term tasks: undated work kept on the dashboard. Priority uses the four quadrants of the Eisenhower matrix (urgent × important); \"linked tasks\" were pulled out of it as dated tasks",
"- 할 일: [x]는 완료, [ ]는 미완료. \"예상\"은 미리 적은 예상 시간, \"실제\"는 그 할 일로 잰 시간의 합. \"배정\"은 하려고 정해 둔 시간대, \"옮김\"은 처음 계획한 날에서 다른 날로 미룬 것": "- Tasks: [x] done, [ ] not done. \"est.\" is the estimated time entered beforehand, \"actual\" is the total time tracked for the task. \"scheduled\" is the time slot set aside, \"moved\" means postponed from the originally planned day",
