". 꽤 길어서 AI가 한 번에 다 읽지 못할 수 있어요. 기간을 줄이거나 \"날짜별 요약만\"으로 바꿔 보세요.": ". That's quite long — the AI may not read it all at once. Try a shorter period or \"Daily summaries only\".",
