"기간과 내용을 고르면 AI에 붙여넣기 좋은 글로 만들어 줘요. 프롬프트와 데이터가 한 덩어리로 복사돼요.": "Pick a period and what to include, and it becomes text that's easy to paste into an AI. The prompt and data are copied together.",
