"이 기기에서 알림을 껐어요": "Notifications turned off on this device",
"아이폰은 홈 화면에 추가한 Align 앱에서만 알림을 켤 수 있어요": "On iPhone, notifications can only be turned on in the Align app added to the Home Screen",
"이 브라우저는 알림을 지원하지 않아요": "This browser doesn't support notifications",
"알림이 허용되지 않았어요. 아래 안내대로 허용해 주세요": "Notifications weren't allowed. Please allow them as described below",
"알림이 켜졌어요": "Notifications are on",
"이제 이 기기로 Align 알림이 와요": "Align notifications will now come to this device",
"아이폰에서는 홈 화면에 추가한 Align 앱에서만 알림을 받을 수 있어요. Safari 주소로 연 화면에서는 켤 수 없어요.": "On iPhone, you only get notifications in the Align app added to the Home Screen. They can't be turned on from a page opened in Safari.",
"이 브라우저는 알림을 지원하지 않아요.": "This browser doesn't support notifications.",
"이 기기에서 알림을 받고 있어요. ": "Notifications are on for this device. ",
"아이폰은 Align이 화면에 떠 있을 때만 알림이 와요.": "On iPhone, notifications only arrive while Align is on screen.",
"Align이 열려 있으면 창을 내려 두거나 다른 창을 써도 알림이 와요.": "While Align is open, notifications arrive even if the window is minimized or you're using another window.",
"알림이 막혀 있어요. ": "Notifications are blocked. ",
"아이폰 설정 → 알림 → Align에서 허용해 주세요.": "Allow them in iPhone Settings → Notifications → Align.",
"맥의 시스템 설정 → 알림에서 Align(또는 쓰는 브라우저)을 허용하고, 크롬이라면 주소창 왼쪽 아이콘 → 알림도 허용해 주세요.": "Allow Align (or your browser) in macOS System Settings → Notifications, and in Chrome also allow notifications from the icon left of the address bar.",
" 그다음 아래 버튼을 다시 누르세요.": " Then tap the button below again.",
"켜면 뽀모도로가 끝날 때, 할 일 마감 전, 일정 시작 전에 알림이 와요. 알림 허용은 기기마다 따로 해야 해요.": "When on, you get notified when a Pomodoro ends, before task deadlines and before events start. Notifications must be allowed on each device separately.",
"위젯": "Widgets",
"아이폰 홈 화면·잠금 화면 위젯으로 오늘 집중 시간, 할 일, 다가오는 일정을 볼 수 있어요. 무료 앱 Scriptable을 써요. 맥(macOS 14 이상)에서는 아이폰 위젯을 바탕화면에 올릴 수 있어요.": "See today's focus time, tasks and upcoming events in iPhone Home Screen and Lock Screen widgets, using the free app Scriptable. On a Mac (macOS 14 or later) you can place iPhone widgets on the desktop.",
