"에 ": " type ",
"이라고 적으세요. 잠금 화면 위젯에도 똑같이 쓸 수 있어요.": ". This works for Lock Screen widgets too.",
"위젯의 집중 시간 기준": "Widget focus time based on",
"위젯이 다음에 새로 고쳐질 때 바뀌어요": "The widget will change at its next refresh",
"복사했어요. Scriptable에 붙여넣으세요.": "Copied. Paste it into Scriptable.",
"복사하지 못했어요. 다시 해 보세요.": "Couldn't copy. Please try again.",
"위젯 코드 복사": "Copy widget code",
"위젯은 아이폰이 정한 때(보통 15분~1시간마다) 새로 고쳐져요. 위젯을 누르면 Align이 열려요.": "Widgets refresh when iPhone decides (usually every 15 minutes to an hour). Tapping a widget opens Align.",
