"소리 종류": "Sound",
"들어 보기": "Play",
"할 일 마감 몇 분 전 (0이면 끔)": "Minutes before a task deadline (0 = off)",
"일정 시작 몇 분 전 (0이면 끔)": "Minutes before an event starts (0 = off)",
"시각 없이 날짜만 정한 마감은 그날 아침 9시에 알려 줘요. 뽀모도로 소리는 위 타이머 카드의 \"끝날 때 알림음\"으로 켜고 꺼요. 아이폰은 무음 모드(옆 스위치)를 풀어야 소리가 나요.": "Deadlines with only a date (no time) are announced at 9 AM that day. The Pomodoro sound is turned on or off with \"Sound when time's up\" on the timer card above. On iPhone, turn off silent mode (side switch) to hear sounds.",
"공유하지 못했어요. 다시 해 보세요.": "Couldn't share. Please try again.",
"예상": "Est.",
"매주 이 요일": "Every week on this day",
"시각을 비워 두면 그날이 끝날 때까지가 마감이에요.": "If you leave the time blank, the deadline is the end of that day.",
"한 칸은 10분. 빈 칸을 누르거나 끌어서(폰에서는 꾹 누른 채 끌어서) 기록·할 일 배정·일정을 추가해요. 색 띠는 한 기록, 점선 칸은 시간을 배정한 할 일, 옅게 칠한 넓은 띠는 시간표의 고정 일정이에요. 고정 일정 이름을 누르면 그 날만 시간을 바꾸거나 쉴 수 있어요.": "Each cell is 10 minutes. Tap or drag across empty cells (on a phone, press and hold, then drag) to add a session, schedule a task or add an event. Color strips are sessions, dashed boxes are tasks with scheduled time, and wide light bands are fixed timetable events. Tap a fixed event's name to change or skip just that day.",
