"생선 가게 아저씨가 날 알아봤어. 냐옹~ 단골이 됐어": "The fishmonger recognized me. Meow~ I'm a regular now.",
"달 위의 거대한 상자": "The Giant Box on the Moon",
"달에 상자가 있더라. 들어갔어. 당연하지": "There was a box on the moon. I got in. Obviously.",
