"세상에서 제일 좋은 막대기야! 너 줄게!": "It's the best stick in the world! For you!",
"해변의 침 묻은 공": "Slobbery Beach Ball",
"바다까지 굴러간 공을 끝까지 쫓아왔어": "Chased it all the way into the sea.",
"우주 최고 산책 트로피": "Galaxy Best Walk Trophy",
"꼬리 흔들기 대회 은하 1등 상이야, 멍!": "First place in the intergalactic tail-wag contest. Woof!",
"동네 산책로": "The Neighborhood Walk",
"멍멍! 전봇대마다 냄새 맡았어! 다음엔 같이 가자!": "Woof! I sniffed every lamppost! Come with me next time!",
"넓은 모래사장": "The Big Sandy Beach",
"파도한테 짖었더니 도망갔다가 또 왔어! 최고야!": "I barked at a wave, it ran off, then came back! Best day!",
