"별이 다 간식 모양이야! 꼬리가 멈추질 않아!": "Every star is shaped like a treat! My tail won't stop!",
"갓 뽑은 텃밭 당근": "Fresh Garden Carrot",
"할머니 텃밭에서 오물오물 한 입만 먹고 왔어": "From Grandma's garden. I only took one nibble.",
"초원의 네잎클로버": "Meadow Four-Leaf Clover",
"깡총깡총 뛰다 발견했어. 행운 나눠 줄게": "Found it mid-hop. Sharing the luck with you.",
"달토끼의 떡메": "Moon Rabbit's Mallet",
"달토끼 언니가 떡 찧던 걸 빌려줬어": "The Moon Rabbit lent me her rice-cake mallet.",
"아파트 뒤 화단": "Flowerbed Behind the Building",
"조용히 오물오물 풀 먹고 있어. 아무한테도 말하지 마": "Quietly munching grass here. Don't tell anyone.",
"끝없는 당근밭": "Endless Carrot Fields",
"당근이 너무 많아서 귀가 쫑긋 서 버렸어!": "So many carrots my ears shot straight up!",
"달토끼 떡방아 마을": "Moon Rabbit Rice-Cake Village",
"달에서 떡 찧는 중! 쿵더쿵 깡총! 너 줄 것도 찧어": "Pounding rice cakes on the moon! Making some for you too.",
"마당의 모이 한 줌": "Handful of Yard Seeds",
"졸졸 따라가다 주웠어. 반 나눠 줄게, 삐약": "Picked them up while tagging along. Half for you, peep.",
"멋진 수탉 깃털": "Fancy Rooster Feather",
"닭 아저씨한테 받았어. 나도 언젠가 이렇게!": "A rooster gave it to me. I'll have one someday!",
"첫 번째 황금 알 껍질": "The First Golden Eggshell",
"세상 모든 병아리가 처음 깨고 나온 알이래": "They say every chick in the world hatched from this one.",
"할머니네 닭장": "Grandma's Henhouse",
"삐약! 닭들 사이에 섞여 봤는데 아무도 몰랐어": "Peep! I blended in with the hens and nobody noticed.",
"해바라기 들판": "Sunflower Fields",
"해바라기가 나보다 백 배 커! 햇살이 따뜻해": "The sunflowers are 100x taller than me! So warm here.",
"새벽을 여는 언덕": "The Hill Where Dawn Begins",
"첫 꼬끼오 연습했어! 아직 삐약이었지만…": "Practiced my first cock-a-doodle! Still came out a peep…",
"볼에 넣어 온 해바라기씨": "Cheek-Stuffed Sunflower Seeds",
"볼 가득 넣어 왔어! 조금 축축할 수도 있어": "Carried them in my cheeks! Might be a bit damp.",
"놀이공원 미니 쳇바퀴": "Theme Park Mini Wheel",
"관람차 보고 감동해서 작은 걸로 사 왔어": "Saw a Ferris wheel and got inspired. Bought a tiny one.",
"전설의 간식 저장고 지도": "Legendary Snack Stash Map",
"숨겨 둔 간식이 다 여기 있었어! 드디어 찾았어": "All my hidden snacks were here! Finally found them!",
"소파 밑 비밀 기지": "Secret Base Under the Couch",
"찍찍! 여기 간식 세 개 숨겼어. 비밀이야": "Squeak! Hid three snacks here. It's a secret.",
"한밤의 놀이공원": "Theme Park at Night",
"밤이 되니 힘이 나! 롤러코스터 열 번 탔어!": "Night gives me power! Rode the coaster ten times!",
"해바라기씨 행성": "Planet Sunflower Seed",
"땅이 전부 해바라기씨야! 볼이 터질 것 같아!": "The whole ground is seeds! My cheeks might burst!",
"동네 연못 연잎": "Pond Lily Pad",
"폴짝 뛰어 앉았던 연잎이야. 아직 축축해": "The pad I landed on. Still damp.",
"장마철 개구리 우산": "Rainy Season Umbrella",
"비 오는 날이 좋지만 너는 젖으면 안 되니까": "I love rain, but you shouldn't get wet.",
"개구리 왕자의 왕관": "Frog Prince's Crown",
"뽀뽀하면 왕자가 된대. 나는 그냥 개구리할래": "A kiss turns you into a prince. I'll stay a frog.",
"비 오는 놀이터": "Playground in the Rain",
"개굴개굴! 웅덩이마다 다 뛰어 봤어. 완전 신나!": "Ribbit! I jumped in every puddle. Best day ever!",
"열대우림 늪": "Rainforest Swamp",
"여기 파리가 엄청 커! 혀가 모자랄 지경이야": "The flies here are huge! My tongue isn't long enough.",
"달빛 개구리 대합창장": "Moonlit Frog Grand Chorus",
"전 세계 개구리랑 밤 합창했어! 내가 솔로였어!": "Sang the night chorus with every frog on Earth! I got the solo!",
"냉동실 얼음 한 조각": "Freezer Ice Cube",
"추운 게 좋아서 냉동실에 다녀왔어. 시원하지?": "I love the cold, so I visited the freezer. Chilly, right?",
"북극 수산시장 정어리": "Fish Market Sardine",
"뒤뚱뒤뚱 줄 서서 산 제일 싱싱한 생선이야": "Waddled in line for the freshest one.",
"남극 최고의 조약돌": "Antarctica's Finest Pebble",
"펭귄은 좋아하는 친구한테 조약돌을 줘. 너 줄게": "Penguins give pebbles to the ones they love. Here.",
"동네 아이스링크": "Local Ice Rink",
"미끄럼 타려다 배로 한 바퀴 돌았어. 펭!": "Tried to slide and spun around on my belly. Peng!",
"차가운 북쪽 바다": "The Cold Northern Sea",
"고래랑 같이 헤엄쳤어. 생선은 내가 더 많이 먹었어": "Swam with a whale. I ate more fish, though.",
"남극의 오로라 밤": "Antarctic Aurora Night",
"다 같이 모여서 오로라 봤어. 하나도 안 추웠어": "We huddled and watched the aurora. Not cold at all.",
"담장 위 포도 한 송이": "Grapes From the Fence",
"높아서 못 딴다고? 영리하게 따 왔지. 안 시어": "Too high? I got them cleverly. Not sour at all.",
"여우 축제 가면": "Fox Festival Mask",
"숨바꼭질할 때 쓰면 아무도 날 못 찾아": "Wear it for hide-and-seek. No one finds me.",
"구미호의 여우 구슬": "Nine-Tailed Fox's Orb",
"꼬리 아홉 개 할머니한테 내기로 따 왔어, 캥!": "Won it in a bet with a nine-tailed elder. Kyang!",
"동네 포도밭": "The Local Vineyard",
"포도는 시지 않아. 직접 확인했어. 한 송이 전부": "Grapes aren't sour. I checked. The whole bunch.",
"여우 신사 붉은 문길": "Fox Shrine Gate Path",
"빨간 문이 천 개야! 숨바꼭질하기 딱 좋아, 캥캥": "A thousand red gates! Perfect for hide-and-seek.",
