"달빛 산책 중에 구미호를 만났어. 내 꼬리가 더 폭신해": "Met a nine-tailed fox on my moonwalk. Mine's fluffier.",
"편의점 꿀 스틱": "Convenience Store Honey Stick",
"꿀 냄새 따라가다 보니 편의점이었어, 곰곰…": "Followed the honey smell. It was a corner store.",
"강에서 잡은 연어": "River-Caught Salmon",
"폭포에서 입 벌리고 있었더니 들어왔어": "Just held my mouth open at the falls. It jumped in.",
"끝없는 꿀단지": "The Bottomless Honey Pot",
"아무리 먹어도 줄지 않는 전설의 꿀단지야": "A legendary pot that never runs out.",
"뒷산 벌집 나무": "The Beehive Tree Up the Hill",
"꿀 냄새 난다… 벌한테 쫓겼지만 맛은 봤어": "Smelled honey… got chased by bees, but I got a taste.",
"연어 폭포 계곡": "Salmon Falls Valley",
"연어 잡으러 왔어! 너 줄 것도 한 마리 잡을게": "Came to catch salmon! I'll grab one for you too.",
"전설의 겨울잠 동굴": "Legendary Hibernation Cave",
"여기서 겨울잠 자면 꿀 꿈만 꾼대… 쿨쿨… 꼭 안아 줄게": "Sleep here and you only dream of honey… zzz… hugs.",
"반짝이는 동전 하나": "One Shiny Coin",
"길에서 주웠어! 내 보물 더미의 첫 번째야": "Found it on the street! First of my treasure hoard.",
"화산에서 구운 마시멜로": "Volcano-Roasted Marshmallow",
"내 작은 불꽃 말고 진짜 화산으로 구웠어": "Not my little flame—roasted on a real volcano.",
"용왕의 여의주": "The Dragon King's Pearl",
"용이라면 누구나 꿈꾸는 구슬! 크게 날 거야": "Every dragon dreams of it! I'll fly big someday.",
"옥상 날개 연습장": "Rooftop Flight School",
"날개 연습 중! 오늘 세 걸음 날았어. 걸었나?": "Wing practice! Flew three steps today. Or walked?",
"불꽃 화산 섬": "Fire Volcano Island",
"화산이 나보다 불을 잘 뿜어. 으르릉… 연습해야지": "The volcano breathes fire better than me. Grr… must practice.",
"구름 위 용의 성": "Dragon Castle Above the Clouds",
"용들의 성에 왔어! 보물 위에서 자는 게 꿈이었어": "Made it to the dragon castle! Sleeping on treasure—dream come true.",
"과일가게 꿀사과": "Honey Apple From the Market",
"먹는 게 제일 좋아! 한 입 먹은 건 비밀이야": "Food is the best! The bite mark is a secret.",
"온천 마을 계란": "Hot Spring Village Egg",
"온천물에 삶은 계란이야. 따끈따끈, 꿀꿀!": "Boiled in spring water. Toasty! Oink!",
"세계 먹방 대회 금메달": "World Eating Contest Gold",
"꿀꿀! 사과 백 개 먹고 우승했어. 배부르니 졸려": "Ate 100 apples and won! So full… so sleepy.",
"비 온 뒤 진흙 웅덩이": "Mud Puddle After the Rain",
"진흙 목욕 했어! 완전 개운해. 씻고 갈게, 꿀꿀": "Had a mud bath! So refreshing. I'll rinse off first. Oink.",
"산속 노천 온천": "Mountain Open-Air Hot Spring",
"온천 최고! 코가 간질간질할 만큼 따뜻해": "Hot springs rule! Warm enough to tickle my snout.",
"디저트 무한 왕국": "Infinite Dessert Kingdom",
"성벽이 케이크야! 다 먹으면 집에 갈게… 언젠가": "The castle walls are cake! I'll come home once I finish… someday.",
"공원 잔디 한 줌": "A Tuft of Park Grass",
"풀이 맛있어서 너도 맛보라고 가져왔어, 메에~": "So tasty I brought you some. Baa~",
"내 털로 짠 목도리": "Scarf Knit From My Wool",
"털 깎는 날 기념으로 짰어. 폭신폭신하지?": "Knit on shearing day. Super fluffy, right?",
"구름 양떼의 솜뭉치": "Cloud Flock Fluff",
"하늘의 구름 양들이 털을 한 줌 나눠 줬어": "The cloud sheep in the sky shared some fluff.",
"동네 잔디 공원": "The Grassy Neighborhood Park",
"메에~ 잔디 먹다가 낮잠 잤어. 털에 풀 붙었어": "Baa~ Napped while grazing. Grass stuck in my wool.",
"알프스 초원": "Alpine Meadows",
"들판에서 실컷 뛰었어! 양 친구 백 마리 생겼어": "Ran all over the fields! Made 100 sheep friends.",
"양 세는 꿈나라": "Counting-Sheep Dreamland",
"사람들이 세는 양이 나였어! 한 마리, 쿨…": "Turns out I'm the sheep people count! One sheep… zzz",
"편의점 컵라면": "Convenience Store Cup Ramen",
"이름이 나랑 같은 라면이야! 반은 내가 먹었어": "The ramen with my name! I ate half.",
"둔갑술 나뭇잎": "Shapeshifting Leaf",
"머리에 올리면 변신한대. 아직 연습 중이야": "Put it on your head to transform. Still practicing.",
"전설의 라면 냄비": "The Legendary Ramen Pot",
"이 냄비로 끓이면 면이 절대 안 불어! 너굴!": "Noodles cooked in it never go soggy! Neogul!",
"새벽 편의점": "The 3 A.M. Corner Store",
"밤 산책은 내 특기! 편의점 아저씨랑 친해졌어": "Night walks are my thing! Made friends with the clerk.",
"그리운 고향 숲": "My Old Home Forest",
"숲이 그리워서 왔어. 꼬리 줄무늬도 여기서 생겼대": "Missed the forest, so I came. It's where I got my stripes.",
"너구리 둔갑 대회장": "The Great Tanuki Shapeshift Contest",
"찻주전자로 변신해서 우승했어! 꼬리는 삐져나왔지만": "Won by turning into a teapot! My tail stuck out, though.",
"화분 속 대나무": "Potted Bamboo",
"동네 꽃집에서 샀어. 먹으려다 참았어": "From the flower shop. Resisted eating it.",
"쓰촨 찐빵": "Sichuan Steamed Bun",
"하루 종일 먹고 자다 하나 남겨 왔어": "Ate and slept all day, but saved you one.",
"흑백 유행의 원조 증서": "Original Black & White Certificate",
