"엄마가 팔던 프레첼이란다. 간식 줄까?": "From my old pretzel business. Want a snack?",
"링고 스타 초상화": "Ringo Starr Portrait",
"직접 그린 그림이야. 답장도 받았단다, Hmmm…": "I painted it myself. He even wrote back. Hmmm…",
