"Hmmm… 큰 도시는 시끄럽구나. 호머~! 길 잃지 마": "Hmmm… the big city is so loud. Homer! Don't get lost.",
"내 머리 꼭대기 전망대": "Top of My Hair",
"내 머리 꼭대기에 올라왔단다. 구름 위라니, Hmmm…": "Climbed to the top of my hair. Above the clouds? Hmmm…",
"바트표 새총": "Bart's Slingshot",
"장난칠 거리 장전 완료. Eat my shorts!": "Locked and loaded for pranks. Eat my shorts!",
