"부츠로 엉덩이 차이는 벌 받을 뻔. Don't have a cow!": "Almost got the booting. Don't have a cow, man!",
"도서관 대출 카드": "Library Card",
"도서관 가고 싶었거든. 지식은 힘이야!": "I was dying to go to the library. Knowledge is power!",
"블리딩 검스 머피 LP": "Bleeding Gums Murphy LP",
"재즈 가게에서 찾은 전설의 앨범이야": "A legendary album from a jazz shop.",
"황금 색소폰": "Golden Saxophone",
"재즈의 신이 준 소리야! 한 곡 들어 볼래?": "Sounds like a gift from the jazz gods! Want a tune?",
"스프링필드 도서관": "Springfield Library",
"책 열두 권 빌렸어. 오늘도 성장했어!": "Checked out twelve books. Growing every day!",
"뉴올리언스 재즈 거리": "New Orleans Jazz Street",
"색소폰 한 곡 불었더니 박수 받았어! 완벽해": "Played one tune and got applause! Perfect.",
"미래의 대통령 집무실": "Future Oval Office",
"미래의 나, 대통령 됐어! 첫 공약: 도서관 24시간": "Future me is President! First pledge: 24-hour libraries.",
"예비용 쪽쪽이": "Spare Pacifier",
"*쪽쪽* …엄마 몰래 챙긴 예비용이에요": "*suck suck* …a backup, snuck past Mom.",
"새 파란 리본": "New Blue Bow",
"…! 놀이공원에서 받은 새 리본. 까르르": "…! A new bow from the amusement park. Giggle.",
"첫마디 녹음 테이프": "My First Word, on Tape",
"아무도 못 들은 내 첫마디가 담겼어요. *쪽*": "The first word nobody heard. *suck*",
"에인 랜드 어린이집": "Ayn Rand School for Tots",
"*쪽쪽* 아기들 다 내 편이에요. …!": "*suck suck* All the babies are on my side. …!",
"스프링필드 동물원": "Springfield Zoo",
"곰이랑 눈싸움 이김. *쪽쪽쪽* 까르르": "Won a staring contest with a bear. *suck suck* Giggle.",
"달님 침대": "Moon Crib",
"zZ… 달에서 낮잠. 쪽쪽이는 지구에 두고 옴. …!": "zZ… napping on the Moon. Left the pacifier on Earth. …!",
"베이컨 팬케이크": "Bacon Pancake",
"제이크가 굽던 걸 한 장 몰래 챙겨 왔어요. 아직 따끈해요!": "Swiped one off Jake's griddle. Still warm!",
"초록 모험 가방": "Green Adventure Pack",
"던전에서 주운 보물이 잔뜩 든 핀의 가방이에요": "Finn's backpack, stuffed with dungeon loot.",
"풀의 검": "Grass Sword",
"저주받은 풀의 검! 손에서 안 떨어지는 게 함정이에요": "A cursed grass sword. Catch: it won't let go of your hand.",
"트리하우스": "The Tree Fort",
"제이크랑 트리하우스 지붕에서 별 봤어! 완전 수학적이야!": "Stargazing on the Tree Fort roof with Jake. Mathematical!",
"캔디 왕국": "Candy Kingdom",
"공주님 구해 드렸어! 이번 퀘스트는 진짜 대수적이었다고!": "Rescued a princess! This quest was totally algebraic!",
"우주 감옥 시타델": "The Citadel",
"멀티버스 끝까지 왔어. 모험의 시간은 끝이 없어!": "Made it to the edge of the multiverse. Adventure time never ends!",
"완벽한 샌드위치": "The Perfect Sandwich",
"제이크 특제 샌드위치예요. 세상에서 제일 완벽하대요": "Jake's signature build. Scientifically perfect, he says.",
"제이크의 비올라": "Jake's Viola",
"제이크가 아끼는 비올라예요. 한 곡 뽑아 준대요": "His prized viola. He's itching to play you a tune.",
