"레이디 레이니콘이 떼어 준 무지개 한 조각이에요": "A slice of rainbow from Lady Rainicorn herself.",
"트리하우스 부엌": "Tree Fort Kitchen",
"베이컨 팬케이크 노래 부르면서 요리 중이야, 형제!": "Singing the bacon pancakes song while I cook, bro!",
"레이니콘 하늘길": "Rainicorn Skyway",
"레이니콘이랑 무지개 타고 날았어. 끝내준다, 형제!": "Rode a rainbow with my lady. Awesome, bro!",
"화성": "Mars",
"화성까지 몸을 쭈욱 늘였어! 링컨 대통령도 만났어, 형제": "Stretched all the way to Mars! Met Abe Lincoln, bro.",
"새 게임팩": "New Game Cartridge",
"비모 몸에 쏙 들어가는 새 게임이에요. 같이 할래요?": "Slots right into BMO. Wanna play?",
