"비모가 진짜 소년이라는 증명서! 직접 도장 찍었대요": "Official proof BMO is a real boy. Self-stamped.",
"트리하우스 욕실": "Tree Fort Bathroom",
"욕실 거울 앞에서 축구랑 수다 떨었어! 축구야, 안녕?": "Chatted with Football in the mirror. Hello, Football!",
"MO 공장": "MO Factory",
"비모가 태어난 공장이야! 비모 형제들이 엄청 많아!": "The factory where BMO was born! So many BMO siblings!",
"게임 속 세계": "Inside the Game",
