"공주님 여행용 왕관이에요. 과학적으로 반짝여요": "The princess's spare crown. Scientifically sparkly.",
"마더 검 조각": "Mother Gum Shard",
"캔디 왕국을 만든 태초의 껌 조각이에요. 소중히!": "A piece of the primordial gum that made the Candy Kingdom.",
