"동굴 집 그늘이 최고야. 햇빛은 사양할게": "Nothing beats the shade of my cave. Sun, you can stay out.",
"한밤의 숲 공연": "Midnight Forest Gig",
"밤새 베이스 쳤어. 록 앤 롤! 관객은 전부 유령": "Played bass all night. Rock and roll! Crowd was all ghosts.",
"나이토스피어": "The Nightosphere",
"아빠네 왔어. 감자튀김 얘기 또 꺼냈더니 싸웠지, 흐흐": "Visiting Dad. Brought up the fries again. We fought. Heh.",
"레몬 사탕": "Lemon Candy",
"레몬 사탕이다! 정확히 하나만 먹도록!": "Lemon candy! You may eat EXACTLY one!",
