"드럼 솔로용 얼음 스틱이에요. 손이 좀 시려요": "For drum solos. A little cold on the hands.",
"마법 얼음 왕관": "Magic Ice Crown",
"이게 없으면 마법을 못 써요! 절대 잃어버리면 안 돼요": "No crown, no magic! Never, ever lose it.",
