"공주 필수템이야. 빌려 달라고 하지 마, 됐니?": "Princess essential. Don't ask to borrow it, okay?",
"공주 전용 폰": "Princess Phone",
"드라마가 실시간으로 업데이트되는 폰이야. 충전 필수": "Live drama updates, 24/7. Must stay charged.",
"럼피 왕관 별": "Lumpy Crown Star",
"공주 머리에 달린 그 별이야. 완전 럼피하잖아!": "THE star from her head. So lumpy!",
