"숲에서 혼자 사는 중. 모닥불도 피웠어. 완전 독립녀야": "Living solo in the woods. Made a campfire. Totally independent.",
"럼피 프롬 파티": "Lumpy Prom",
"프롬 왔는데 브래드가 딴 애랑 춤춰. 어머 글롭!": "At prom and Brad's dancing with someone else. Oh my glob!",
