"1974년부터 왼쪽 귀에 단 바로 그 리본이에요": "The very bow on her left ear since 1974.",
"엄마의 부엌": "Mama's Kitchen",
"엄마랑 애플파이 구웠어! 미미 몫도 남겨 둘게": "Baked apple pie with Mama! Saving a slice for Mimmy.",
"런던 시계탑 앞": "Big Ben, London",
"런던 친구들 만났어! 근위병 아저씨는 안 웃더라": "Met friends in London! The guard wouldn't smile, though.",
"꿈의 성에 친구들이 다 모였어. 친구는 많을수록 좋아!": "All my friends in one dream castle. The more friends the better!",
"아몬드 파운드 케이크": "Almond Pound Cake",
"엄마랑 같이 구운 케이크예요. 한 조각 나눠 줄게요": "Baked with Mama. Here's a slice for you.",
"할머니표 목도리": "Grandma's Scarf",
"여행 가서 만난 할머니가 떠 주신 분홍 목도리예요": "A pink scarf Grandma knitted during the visit.",
"멜로디 키": "Melody Key",
"꿈을 지키는 마법 열쇠예요. 엄마 말씀대로 소중히": "A magic key that guards dreams. Kept safe, like Mama said.",
"마리랜드 숲": "Mariland Forest",
"다람쥐 친구들이랑 산책했어~ 엄마가 그러셨어, 길 조심!": "A walk with my squirrel friends~ Mama said watch your step!",
"튤립 꽃밭": "Tulip Fields",
"꽃밭에서 쿠로미를 만났어. 쿠로미는 사실 착한 아이야~": "Ran into Kuromi in the flowers. She's sweet, really~",
"꿈의 나라": "Dream Land",
"꿈의 나라에 왔어~ 모두 사이좋게 지내면 좋겠다": "I'm in Dream Land~ I hope everyone gets along.",
"락교 한 병": "Jar of Rakkyo",
"쿠로미 님 최애 간식이다. 너한텐 안 줘!… 하나만 줄게": "Kuromi's favorite snack. Not sharing! …Okay, one.",
"자물쇠 일기장": "Locked Diary",
"여행 중 쓴 일기장. 마이멜로디 얘기가 반이야": "Trip diary. Half of it is about My Melody.",
"분홍 해골 두건": "Pink Skull Hood",
"쿠로미 님의 상징! 특별히 보여 주는 거니까 감사해": "Kuromi's trademark! Be grateful she's showing you.",
"쿠로미 아지트": "Kuromi's Hideout",
"바쿠가 또 낮잠 잔다. 일기장에 적어 둘 거야": "Baku's napping again. Writing that in my diary.",
