"라이벌네 앞에서 장난 계획 중. 흥, 기대해!": "Plotting a prank outside my rival's house. Hmph, just wait!",
"마리랜드 정복 성": "Conquered Mariland Castle",
"드디어 마리랜드 정복! …근데 성을 핑크로 칠했어": "Mariland is MINE! …I painted the castle pink, though.",
"카페 시나몬 롤빵": "Café Cinnamon Roll",
"카페 시나몬에서 갓 구운 빵이에요. 제 꼬리 닮았죠?": "Fresh from Café Cinnamon. Looks like my tail, right?",
"하늘 산책 풍선": "Sky Walk Balloon",
"하늘에서 같이 날던 풍선이에요. 친구가 됐어요": "We flew side by side up there. Now we're friends.",
"구름 위 무지개": "Above-the-Clouds Rainbow",
"구름 맨 위에서 살짝 떼어 온 무지개 조각이에요": "A bit of rainbow from the very top of the clouds.",
"카페 시나몬": "Café Cinnamon",
"테라스에서 코코아 마셨어. 귀가 펄럭펄럭!": "Cocoa on the terrace. Ears flapping happily!",
"노을 구름 위": "Sunset Clouds",
