"이벤트 상점 보기": "Open the event shop",
"지금은 열린 이벤트가 없어요. 다음 이벤트를 기다려 주세요!": "No event right now. Stay tuned for the next one!",
"{e} 이벤트": "{e} event",
"{d}까지": "until {d}",
"타이머로 집중하면 10분마다 {c} 1개 (한 번에 최대 6개). 모은 {c}으로 한정 옷과 배경을 바꿀 수 있어요. 이벤트가 끝나도 바꾼 건 계속 쓸 수 있어요.": "Focus with the timer to earn 1 {c} every 10 minutes (up to 6 per session). Trade {c} for limited outfits and backgrounds. Everything you trade for stays yours after the event.",
"배경으로 쓰기": "Use as background",
"이벤트가 끝나도 계속 쓸 수 있어요": "Yours to keep after the event",
"배경은 이벤트 기간에는 누구나 쓸 수 있고, 바꿔 두면 이벤트가 끝나도 남아요.": "Anyone can use the background during the event. Trade for it to keep it afterwards.",
