  "기념품 {a} · 엽서 {b} 진열 중":"{a} souvenirs · {b} postcards on display",
  "탐험에서 모은 기념품은 선반에, 엽서는 코르크판에 걸려요. 누르면 크게 볼 수 있어요. 창밖은 지금 시각이에요.":"Souvenirs from expeditions sit on the shelves and postcards hang on the corkboard. Tap one to see it up close. The window shows the time right now.",
  "아직 방이 텅 비었어요. 타이머로 10분 넘게 집중하면 동물이 탐험에서 기념품과 엽서를 가져와요!":"The room is still empty. Focus with the timer for over 10 minutes and your pet brings back souvenirs and postcards!",
