  "{p}이(가) 굴뚝에 끼었어요! 10분은 넘겨야 쏙 빠져나와요":"{p} got stuck in a chimney! Focus over 10 minutes to pop out",
  "타이머로 집중하면 10분마다 {c} 1개 (한 번에 최대 6개). 모은 {c}(으)로 한정 옷과 배경을 바꿀 수 있어요. 이벤트가 끝나도 바꾼 건 계속 쓸 수 있어요.":"Focus with the timer to get 1 {c} every 10 minutes (up to 6 at once). Trade {c} for limited outfits and backgrounds. You keep them after the event ends.",
  "크리스마스":"Christmas",
  "눈송이":"snowflakes",
  "12월 25일까지 집중하면 눈송이를 받아요. 눈송이로 트리 장식과 한정 옷, 크리스마스 마을 배경을 사요. 동물들이 산타에게 편지를 쓰고, 12월엔 어드벤트 캘린더가 열려요. 오래 집중하면 눈사람과 루돌프가 찾아와요!":"Until December 25, focusing earns snowflakes. Spend them on tree ornaments, limited outfits and the Christmas Village background. Your pets write letters to Santa, and the advent calendar opens in December. Focus long enough and a snowman and Rudolph come to visit!",
